package com.Senai.Mubak.model; import java.time.LocalDate; import org.springframework.format.annotation.DateTimeFormat; import jakarta.validation.constraints.*; /** DTO do formulário de cadastro; recebe confirmações antes de virar uma entidade Usuario. */ public class UsuarioForm {@NotBlank String nome,documento,email,confirmacaoEmail,senha,confirmacaoSenha; @NotNull @DateTimeFormat(pattern="dd/MM/yyyy") LocalDate dataNascimento; public String getNome(){return nome;} public void setNome(String v){nome=v;} public String getDocumento(){return documento;} public void setDocumento(String v){documento=v;} public LocalDate getDataNascimento(){return dataNascimento;} public void setDataNascimento(LocalDate v){dataNascimento=v;} public String getEmail(){return email;} public void setEmail(String v){email=v;} public String getConfirmacaoEmail(){return confirmacaoEmail;} public void setConfirmacaoEmail(String v){confirmacaoEmail=v;} public String getSenha(){return senha;} public void setSenha(String v){senha=v;} public String getConfirmacaoSenha(){return confirmacaoSenha;} public void setConfirmacaoSenha(String v){confirmacaoSenha=v;} }